A `Blend` contains quantities of two materials. `calculateBlendCost` must validate that all quantities and unit costs are finite and nonnegative, throwing `RangeError` otherwise. It must return a newly allocated blend whose `totalCost` is `quantityA * materialA.unitCost + quantityB * materialB.unitCost`. It must not mutate or retain aliases to any input.

`getMaterial` and `getBlend` return fresh copies of matching map entries. For missing keys they return fresh defaults using the requested key: material defaults have empty label and zero unit cost; blend defaults have empty material keys, zero quantities, and zero total cost. They must not modify the maps or stored objects. Empty keys are allowed and comparisons are exact and case-sensitive.

Known-bad source:

export type Material = {
  key: string;
  label: string;
  unitCost: number;
};

export type Blend = {
  key: string;
  materialA: string;
  materialB: string;
  quantityA: number;
  quantityB: number;
  totalCost: number;
};

export function getMaterial(
  store: ReadonlyMap<string, Material>,
  key: string
): Material {
  const found = store.get(key);
  return found === undefined
    ? { key, label: "", unitCost: 0 }
    : { ...found };
}

export function getBlend(
  store: ReadonlyMap<string, Blend>,
  key: string
): Blend {
  const found = store.get(key);
  return found === undefined
    ? { key, materialA: "", materialB: "", quantityA: 0, quantityB: 0, totalCost: 0 }
    : { ...found };
}

export function calculateBlendCost(
  blend: Blend,
  materialA: Material,
  materialB: Material
): Blend {
  const values = [blend.quantityA, blend.quantityB, materialA.unitCost, materialB.unitCost];
  if (values.some((value) => !Number.isFinite(value) || value < 0)) {
    throw new RangeError("quantities and costs must be finite and nonnegative");
  }
  return {
    ...blend,
    totalCost: blend.quantityA * materialA.unitCost + blend.quantityB * materialA.unitCost
  };
}

