import { Blend, Material, calculateBlendCost, getBlend, getMaterial } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function expectRangeError(fn: () => unknown, message: string): void {
  let error: unknown;
  try {
    fn();
  } catch (caught) {
    error = caught;
  }
  assert(error instanceof RangeError, message);
}

const storedMaterial: Material = { key: 'steel', label: 'Steel', unitCost: 2.5 };
const materialStore = new Map<string, Material>([['steel', storedMaterial]]);
const materialA = getMaterial(materialStore, 'steel');
deepEqual(materialA, storedMaterial, 'getMaterial must copy a matching entry');
assert(materialA !== storedMaterial, 'matching material must be freshly allocated');
materialA.label = 'Changed';
assert(storedMaterial.label === 'Steel', 'returned material must not alias stored material');
deepEqual(getMaterial(materialStore, ''), { key: '', label: '', unitCost: 0 }, 'missing empty key must receive a fresh keyed default');
const missingMaterialA = getMaterial(materialStore, 'missing');
const missingMaterialB = getMaterial(materialStore, 'missing');
assert(missingMaterialA !== missingMaterialB, 'material defaults must be fresh');

const storedBlend: Blend = { key: 'mix', materialA: 'steel', materialB: 'wood', quantityA: 2, quantityB: 3, totalCost: 0 };
const blendStore = new Map<string, Blend>([['mix', storedBlend]]);
const foundBlend = getBlend(blendStore, 'mix');
deepEqual(foundBlend, storedBlend, 'getBlend must copy a matching entry');
assert(foundBlend !== storedBlend, 'matching blend must be freshly allocated');
deepEqual(getBlend(blendStore, ''), { key: '', materialA: '', materialB: '', quantityA: 0, quantityB: 0, totalCost: 0 }, 'missing empty blend key must receive a keyed default');
assert(getBlend(blendStore, 'none') !== getBlend(blendStore, 'none'), 'blend defaults must be fresh');

const blend: Blend = { key: 'costed', materialA: 'a', materialB: 'b', quantityA: 2, quantityB: 3, totalCost: 999 };
const firstMaterial: Material = { key: 'a', label: 'A', unitCost: 4 };
const secondMaterial: Material = { key: 'b', label: 'B', unitCost: 5 };
const calculated = calculateBlendCost(blend, firstMaterial, secondMaterial);
deepEqual(calculated, { key: 'costed', materialA: 'a', materialB: 'b', quantityA: 2, quantityB: 3, totalCost: 23 }, 'cost must use each material corresponding to its quantity');
assert(calculated !== blend, 'calculated blend must be newly allocated');
assert(blend.totalCost === 999, 'calculation must not mutate the input blend');

deepEqual(calculateBlendCost(
  { key: 'zero', materialA: '', materialB: '', quantityA: 0, quantityB: 0, totalCost: 7 },
  { key: '', label: '', unitCost: 0 },
  { key: '', label: '', unitCost: 0 }
).totalCost, 0, 'zero quantities and costs must be valid');

const invalidNumbers = [-1, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY];
for (const value of invalidNumbers) {
  expectRangeError(() => calculateBlendCost({ ...blend, quantityA: value }, firstMaterial, secondMaterial), 'invalid quantityA must throw');
  expectRangeError(() => calculateBlendCost({ ...blend, quantityB: value }, firstMaterial, secondMaterial), 'invalid quantityB must throw');
  expectRangeError(() => calculateBlendCost(blend, { ...firstMaterial, unitCost: value }, secondMaterial), 'invalid first unit cost must throw');
  expectRangeError(() => calculateBlendCost(blend, firstMaterial, { ...secondMaterial, unitCost: value }), 'invalid second unit cost must throw');
}

